    out[n] = await new Promise(res => {
      const i = new Image();
      i.onload = () => res(i.naturalWidth + 'x' + i.naturalHeight);
      i.onerror = () => res('ERR');
      i.src = '/' + n + '?t=' + Date.now();
    });
  }
  return out;
}

